window.AUTH=window.AUTH||{};window.AUTH["82-1005"]={"d":"82-1005","id":"1983/82-1005","n":"Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc.","src":["osg"],"briefs":[{"k":"reply","label":"Reply brief for the Administrator of the Environmental Protection Agency","date":"","url":"https://www.justice.gov/osg/media/223926/dl?inline","side":"pet","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/chevron-usa-inc-petitioners-v-natural-resources-defense-council-inc-et-al","toa":false,"n":17},{"k":"respondent","label":"Brief for the Administrator of the Environmental Protection Agency","date":"","url":"https://www.justice.gov/osg/media/224271/dl?inline","side":"res","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/chevron-usa-inc-petitioner-v-natural-resources-defense-council-inc-et-al-american-iron-and","toa":false,"n":28}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep467/usrep467837/usrep467837.pdf","tr":false,"items":[{"t":"case","label":"Alabama Power Co. v. Costle","cite":"636 F.2d 323","y":1979,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/636/323/","op":5,"by":{"0":"","1":""}},{"t":"case","label":"Pennhurst State School v. Halderman","cite":"451 U.S. 1","y":1981,"id":"1980/79-1404","sc":1,"sum":"Section 6010 does not create in favor of the mentally retarded any substantive rights to \"appropriate treatment\" in the \"least restrictive\" environment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Chrysler Corp. v. Brown","cite":"441 U.S. 281","y":1979,"id":"1978/77-922","sc":1,"sum":"Petitioner, as a party to numerous Government contracts, was required to comply with Executive Orders 11246 and 11375, which charge the Secretary of Labor with ensuring that corporations that benefit from Government contracts provide equal employment opportunity regardless of race or sex. Regulations promulgated by the Department of Labor's Office of Federal Contract Compliance Programs (OFCCP) require Government …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Clark","cite":"445 U.S. 23","id":"1979/78-1513","sc":1,"sum":"Under the provisions of the Civil Service Retirement Act whereby a deceased federal employee's legitimate children under 18 years of age qualify for survivors' benefits but \"recognized natural\" children under 18 may recover only if they \"lived with the employee... in a regular parent-child relationship,\" a recognized natural child is entitled to survivors' benefits when the child has lived with the deceased employee …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"CPSC v. GTE Sylvania","cite":"447 U.S. 102","y":1980,"id":"1979/79-521","sc":1,"sum":"Section 6 (b) (1) governs the disclosure of records by the Commission pursuant to a request under the FOIA.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"FCC v. National Citizens Committee for Broadcasting","cite":"436 U.S. 775","y":1978,"id":"1977/76-1471","sc":1,"op":1,"sum":"The challenged regulations are valid in their entirety.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"ASARCO, Inc. v. EPA","cite":"578 F.2d 319","y":1978,"url":"https://www.courtlistener.com/c/F.2d/578/319/","op":4,"by":{"0":"","1":""}},{"t":"usc","label":"42 U.S.C. § 1957c-6","url":"https://www.law.cornell.edu/uscode/text/42/1957c-6","subs":["(a)(3)"],"by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 1857c-5","url":"https://www.law.cornell.edu/uscode/text/42/1857c-5","subs":["(a)(2)(D)","(a)(2)"],"tname":"The Public Health and Welfare","by":{"0":"","1":""}},{"t":"usc","label":"42 U.S.C. § 1857c-6","url":"https://www.law.cornell.edu/uscode/text/42/1857c-6","tname":"The Public Health and Welfare","by":{"0":"","1":""}},{"t":"usc","label":"42 U.S.C. § 7410","url":"https://www.law.cornell.edu/uscode/text/42/7410","subs":["(a)(2)(D)","(a)(2)(I)"],"stext":{"head":"§7410. State implementation plans for national primary and secondary ambient air quality standards","paras":[[0,"(a) Adoption of plan by State; submission to Administrator; content of plan; revision; new sources; indirect source review program; supplemental or intermittent control systems"],[0,"(1) Each State shall, after reasonable notice and public hearings, adopt and submit to the Administrator, within 3 years (or such shorter period as the Administrator may prescribe) after the promulgation of a national primary ambient air quality standard (or any revision thereof) under section 7409 of this title for any air pollutant, a plan which provides for implementation, maintenance, and enforcement of such primary standard in each air quality control region (or portion thereof) within such State. In addition, such State shall adopt and submit to the Administrator (either as a part of a plan submitted under the preceding sentence or separately) within 3 years (or such shorter period as the Administrator may prescribe) after the promulgation of a national ambient air quality secondary standard (or revision thereof), a plan which provides for implementation, maintenance, and enforcement of such secondary standard in each air quality control region (or portion thereof) within such State. Unless a separate public hearing is provided, each State shall consider its plan implementing such secondary standard at the hearing required by the first sentence of this paragraph."],[0,"(2) Each implementation plan submitted by a State under this chapter shall be adopted by the State after reasonable notice and public hearing. Each such plan shall—"],[1,"(A) include enforceable emission limitations and other control measures, means, or techniques (including economic incentives such as fees, marketable permits, and auctions of emissions rights), as well as schedules and timetables for compliance, as may be necessary or appropriate to meet the applicable requirements of this chapter;"],[1,"(B) provide for establishment and operation of appropriate devices, methods, systems, and procedures necessary to—"],[2,"(i) monitor, compile, and analyze data on ambient air quality, and"],[2,"(ii) upon request, make such data available to the Administrator;"],[1,"(C) include a program to provide for the enforcement of the measures described in subparagraph (A), and regulation of the modification and construction of any stationary source within the areas covered by the plan as necessary to assure that national ambient air quality standards are achieved, including a permit program as required in parts C and D;"],[1,"(D) contain adequate provisions—"],[2,"(i) prohibiting, consistent with the provisions of this subchapter, any source or other type of emissions activity within the State from emitting any air pollutant in amounts which will—"],[3,"(I) contribute significantly to nonattainment in, or interfere with maintenance by, any other State with respect to any such national primary or secondary ambient air quality standard, or"],[3,"(II) interfere with measures required to be included in the applicable implementation plan for any other State under part C to prevent significant deterioration of air quality or to protect visibility,"],[2,"(ii) insuring compliance with the applicable requirements of sections 7426 and 7415 of this title (relating to interstate and international pollution abatement);"],[1,"(E) provide (i) necessary assurances that the State (or, except where the Administrator deems inappropriate, the general purpose local government or governments, or a regional agency designated by the State or general purpose local governments for such purpose) will have adequate personnel, funding, and authority under State (and, as appropriate, local) law to carry out such implementation plan (and is not prohibited by any provision of Federal or State law from carrying out such implementation plan or portion thereof), (ii) requirements that the State comply with the requirements respecting State boards under section 7428 of this title, and (iii) necessary assurances that, where the State has relied on a local or regional government, agency, or instrumentality for the implementation of any plan provision, the State has responsibility for ensuring adequate implementation of such plan provision;"],[1,"(F) require, as may be prescribed by the Administrator—"],[2,"(i) the installation, maintenance, and replacement of equipment, and the implementation of other necessary steps, by owners or operators of stationary sources to monitor emissions from such sources,"],[2,"(ii) periodic reports on the nature and amounts of emissions and emissions-related data from such sources, and"],[2,"(iii) correlation of such reports by the State agency with any emission limitations or standards established pursuant to this chapter, which reports shall be available at reasonable times for public inspection;"],[1,"(G) provide for authority comparable to that in section 7603 of this title and adequate contingency plans to implement such authority;"],[1,"(H) provide for revision of such plan—"],[2,"(i) from time to time as may be necessary to take account of revisions of such national primary or secondary ambient air quality standard or the availability of improved or more expeditious methods of attaining such standard, and"],[2,"(ii) except as provided in paragraph (3)(C), whenever the Administrator finds on the basis of information available to the Administrator that the plan is substantially inadequate to attain the national ambient air quality standard which it implements or to otherwise comply with any additional requirements established under this chapter;"],[1,"(I) in the case of a plan or plan revision for an area designated as a nonattainment area, meet the applicable requirements of part D (relating to nonattainment areas);"],[1,"(J) meet the applicable requirements of section 7421 of this title (relating to consultation), section 7427 of this title (relating to public notification), and part C (relating to prevention of significant deterioration of air quality and visibility protection);"],[1,"(K) provide for—"],[2,"(i) the performance of such air quality modeling as the Administrator may prescribe for the purpose of predicting the effect on ambient air quality of any emissions of any air pollutant for which the Administrator has established a national ambient air quality standard, and"],[2,"(ii) the submission, upon request, of data related to such air quality modeling to the Administrator;"],[1,"(L) require the owner or operator of each major stationary source to pay to the permitting authority, as a condition of any permit required under this chapter, a fee sufficient to cover—"],[2,"(i) the reasonable costs of reviewing and acting upon any application for such a permit, and"],[2,"(ii) if the owner or operator receives a permit for such source, the reasonable costs of implementing and enforcing the terms and conditions of any such permit (not including any court costs or other costs associated with any enforcement action),"],[1,"until such fee requirement is superseded with respect to such sources by the Administrator's approval of a fee program under subchapter V; and"],[1,"(M) provide for consultation and participation by local political subdivisions affected by the plan."],[0,"(3)(A) Repealed. Pub. L. 101–549, title I, §101(d)(1), Nov. 15, 1990, 104 Stat. 2409."],[0,"(B) As soon as practicable, the Administrator shall, consistent with the purposes of this chapter and the Energy Supply and Environmental Coordination Act of 1974 [15 U.S.C. 791 et seq.], review each State's applicable implementation plans and report to the State on whether such plans can be revised in relation to fuel burning stationary sources (or persons supplying fuel to such sources) without interfering with the attainment and maintenance of any national ambient air quality standard within the period permitted in this section. If the Administrator determines that any such plan can be revised, he shall notify the State that a plan revision may be submitted by the State. Any plan revision which is submitted by the State shall, after public notice and opportunity for public hearing, be approved by the Administrator if the revision relates only to fuel burning stationary sources (or persons supplying fuel to such sources), and the plan as revised complies with paragraph (2) of this subsection. The Administrator shall approve or disapprove any revision no later than three months after its submission."],[0,"(C) Neither the State, in the case of a plan (or portion thereof) approved under this subsection, nor the Administrator, in the case of a plan (or portion thereof) promulgated under subsection (c), shall be required to revise an applicable implementation plan because one or more exemptions under section 7418 of this title (relating to Federal facilities), enforcement orders under section 7413(d) 1 of this title, suspensions under subsection (f) or (g) (relating to temporary energy or economic authority), orders under section 7419 of this title (relating to primary nonferrous smelters), or extensions of compliance in decrees entered under section 7413(e) 1 of this title (relating to iron- and steel-producing operations) have been granted, if such plan would have met the requirements of this section if no such exemptions, orders, or extensions had been granted."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7410?type=usc&year=mostrecent&link-type=html"},"head":"§7410. State implementation plans for national primary and secondary ambient air quality standards","tname":"The Public Health and Welfare","by":{"0":"","1":""}},{"t":"usc","label":"42 U.S.C. § 7602","url":"https://www.law.cornell.edu/uscode/text/42/7602","subs":["(j)"],"stext":{"head":"§7602. Definitions","paras":[[0,"When used in this chapter—"],[0,"(a) The term \"Administrator\" means the Administrator of the Environmental Protection Agency."],[0,"(b) The term \"air pollution control agency\" means any of the following:"],[1,"(1) A single State agency designated by the Governor of that State as the official State air pollution control agency for purposes of this chapter."],[1,"(2) An agency established by two or more States and having substantial powers or duties pertaining to the prevention and control of air pollution."],[1,"(3) A city, county, or other local government health authority, or, in the case of any city, county, or other local government in which there is an agency other than the health authority charged with responsibility for enforcing ordinances or laws relating to the prevention and control of air pollution, such other agency."],[1,"(4) An agency of two or more municipalities located in the same State or in different States and having substantial powers or duties pertaining to the prevention and control of air pollution."],[1,"(5) An agency of an Indian tribe."],[0,"(c) The term \"interstate air pollution control agency\" means—"],[1,"(1) an air pollution control agency established by two or more States, or"],[1,"(2) an air pollution control agency of two or more municipalities located in different States."],[0,"(d) The term \"State\" means a State, the District of Columbia, the Commonwealth of Puerto Rico, the Virgin Islands, Guam, and American Samoa and includes the Commonwealth of the Northern Mariana Islands."],[0,"(e) The term \"person\" includes an individual, corporation, partnership, association, State, municipality, political subdivision of a State, and any agency, department, or instrumentality of the United States and any officer, agent, or employee thereof."],[0,"(f) The term \"municipality\" means a city, town, borough, county, parish, district, or other public body created by or pursuant to State law."],[0,"(g) The term \"air pollutant\" means any air pollution agent or combination of such agents, including any physical, chemical, biological, radioactive (including source material, special nuclear material, and byproduct material) substance or matter which is emitted into or otherwise enters the ambient air. Such term includes any precursors to the formation of any air pollutant, to the extent the Administrator has identified such precursor or precursors for the particular purpose for which the term \"air pollutant\" is used."],[0,"(h) All language referring to effects on welfare includes, but is not limited to, effects on soils, water, crops, vegetation, manmade materials, animals, wildlife, weather, visibility, and climate, damage to and deterioration of property, and hazards to transportation, as well as effects on economic values and on personal comfort and well-being, whether caused by transformation, conversion, or combination with other air pollutants."],[0,"(i) The term \"Federal land manager\" means, with respect to any lands in the United States, the Secretary of the department with authority over such lands."],[0,"(j) Except as otherwise expressly provided, the terms \"major stationary source\" and \"major emitting facility\" mean any stationary facility or source of air pollutants which directly emits, or has the potential to emit, one hundred tons per year or more of any air pollutant (including any major emitting facility or source of fugitive emissions of any such pollutant, as determined by rule by the Administrator)."],[0,"(k) The terms \"emission limitation\" and \"emission standard\" mean a requirement established by the State or the Administrator which limits the quantity, rate, or concentration of emissions of air pollutants on a continuous basis, including any requirement relating to the operation or maintenance of a source to assure continuous emission reduction, and any design, equipment, work practice or operational standard promulgated under this chapter..1"],[0,"(l) The term \"standard of performance\" means a requirement of continuous emission reduction, including any requirement relating to the operation or maintenance of a source to assure continuous emission reduction."],[0,"(m) The term \"means of emission limitation\" means a system of continuous emission reduction (including the use of specific technology or fuels with specified pollution characteristics)."],[0,"(n) The term \"primary standard attainment date\" means the date specified in the applicable implementation plan for the attainment of a national primary ambient air quality standard for any air pollutant."],[0,"(o) The term \"delayed compliance order\" means an order issued by the State or by the Administrator to an existing stationary source, postponing the date required under an applicable implementation plan for compliance by such source with any requirement of such plan."],[0,"(p) The term \"schedule and timetable of compliance\" means a schedule of required measures including an enforceable sequence of actions or operations leading to compliance with an emission limitation, other limitation, prohibition, or standard."],[0,"(q) For purposes of this chapter, the term \"applicable implementation plan\" means the portion (or portions) of the implementation plan, or most recent revision thereof, which has been approved under section 7410 of this title, or promulgated under section 7410(c) of this title, or promulgated or approved pursuant to regulations promulgated under section 7601(d) of this title and which implements the relevant requirements of this chapter."],[0,"(r) Indian Tribe.—The term \"Indian tribe\" means any Indian tribe, band, nation, or other organized group or community, including any Alaska Native village, which is Federally recognized as eligible for the special programs and services provided by the United States to Indians because of their status as Indians."],[0,"(s) VOC.—The term \"VOC\" means volatile organic compound, as defined by the Administrator."],[0,"(t) PM–10.—The term \"PM–10\" means particulate matter with an aerodynamic diameter less than or equal to a nominal ten micrometers, as measured by such method as the Administrator may determine."],[0,"(u) NAAQS and CTG.—The term \"NAAQS\" means national ambient air quality standard. The term \"CTG\" means a Control Technique Guideline published by the Administrator under section 7408 of this title."],[0,"(v) NOx.—The term \"NOx\" means oxides of nitrogen."],[0,"(w) CO.—The term \"CO\" means carbon monoxide."],[0,"(x) Small Source.—The term \"small source\" means a source that emits less than 100 tons of regulated pollutants per year, or any class of persons that the Administrator determines, through regulation, generally lack technical ability or knowledge regarding control of air pollution."],[0,"(y) Federal Implementation Plan.—The term \"Federal implementation plan\" means a plan (or portion thereof) promulgated by the Administrator to fill all or a portion of a gap or otherwise correct all or a portion of an inadequacy in a State implementation plan, and which includes enforceable emission limitations or other control measures, means or techniques (including economic incentives, such as marketable permits or auctions of emissions allowances), and provides for attainment of the relevant national ambient air quality standard."],[0,"(z) Stationary Source.—The term \"stationary source\" means generally any source of an air pollutant except those emissions resulting directly from an internal combustion engine for transportation purposes or from a nonroad engine or nonroad vehicle as defined in section 7550 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7602?type=usc&year=mostrecent&link-type=html"},"head":"§7602. Definitions","tname":"The Public Health and Welfare","by":{"0":"","1":""}},{"t":"usc","label":"42 U.S.C. § 7502","url":"https://www.law.cornell.edu/uscode/text/42/7502","subs":["(b)"],"stext":{"head":"§7502. Nonattainment plan provisions in general","paras":[[0,"(a) Classifications and attainment dates"],[0,"(1) Classifications"],[1,"(A) On or after the date the Administrator promulgates the designation of an area as a nonattainment area pursuant to section 7407(d) of this title with respect to any national ambient air quality standard (or any revised standard, including a revision of any standard in effect on November 15, 1990), the Administrator may classify the area for the purpose of applying an attainment date pursuant to paragraph (2), and for other purposes. In determining the appropriate classification, if any, for a nonattainment area, the Administrator may consider such factors as the severity of nonattainment in such area and the availability and feasibility of the pollution control measures that the Administrator believes may be necessary to provide for attainment of such standard in such area."],[1,"(B) The Administrator shall publish a notice in the Federal Register announcing each classification under subparagraph (A), except the Administrator shall provide an opportunity for at least 30 days for written comment. Such classification shall not be subject to the provisions of sections 553 through 557 of title 5 (concerning notice and comment) and shall not be subject to judicial review until the Administrator takes final action under subsection (k) or (l) of section 7410 of this title (concerning action on plan submissions) or section 7509 of this title (concerning sanctions) with respect to any plan submissions required by virtue of such classification."],[1,"(C) This paragraph shall not apply with respect to nonattainment areas for which classifications are specifically provided under other provisions of this part."],[0,"(2) Attainment dates for nonattainment areas"],[1,"(A) The attainment date for an area designated nonattainment with respect to a national primary ambient air quality standard shall be the date by which attainment can be achieved as expeditiously as practicable, but no later than 5 years from the date such area was designated nonattainment under section 7407(d) of this title, except that the Administrator may extend the attainment date to the extent the Administrator determines appropriate, for a period no greater than 10 years from the date of designation as nonattainment, considering the severity of nonattainment and the availability and feasibility of pollution control measures."],[1,"(B) The attainment date for an area designated nonattainment with respect to a secondary national ambient air quality standard shall be the date by which attainment can be achieved as expeditiously as practicable after the date such area was designated nonattainment under section 7407(d) of this title."],[1,"(C) Upon application by any State, the Administrator may extend for 1 additional year (hereinafter referred to as the \"Extension Year\") the attainment date determined by the Administrator under subparagraph (A) or (B) if—"],[2,"(i) the State has complied with all requirements and commitments pertaining to the area in the applicable implementation plan, and"],[2,"(ii) in accordance with guidance published by the Administrator, no more than a minimal number of exceedances of the relevant national ambient air quality standard has occurred in the area in the year preceding the Extension Year."],[1,"No more than 2 one-year extensions may be issued under this subparagraph for a single nonattainment area."],[1,"(D) This paragraph shall not apply with respect to nonattainment areas for which attainment dates are specifically provided under other provisions of this part."],[0,"(b) Schedule for plan submissions"],[0,"At the time the Administrator promulgates the designation of an area as nonattainment with respect to a national ambient air quality standard under section 7407(d) of this title, the Administrator shall establish a schedule according to which the State containing such area shall submit a plan or plan revision (including the plan items) meeting the applicable requirements of subsection (c) and section 7410(a)(2) of this title. Such schedule shall at a minimum, include a date or dates, extending no later than 3 years from the date of the nonattainment designation, for the submission of a plan or plan revision (including the plan items) meeting the applicable requirements of subsection (c) and section 7410(a)(2) of this title."],[0,"(c) Nonattainment plan provisions"],[0,"The plan provisions (including plan items) required to be submitted under this part shall comply with each of the following:"],[0,"(1) In general"],[1,"Such plan provisions shall provide for the implementation of all reasonably available control measures as expeditiously as practicable (including such reductions in emissions from existing sources in the area as may be obtained through the adoption, at a minimum, of reasonably available control technology) and shall provide for attainment of the national primary ambient air quality standards."],[0,"(2) RFP"],[1,"Such plan provisions shall require reasonable further progress."],[0,"(3) Inventory"],[1,"Such plan provisions shall include a comprehensive, accurate, current inventory of actual emissions from all sources of the relevant pollutant or pollutants in such area, including such periodic revisions as the Administrator may determine necessary to assure that the requirements of this part are met."],[0,"(4) Identification and quantification"],[1,"Such plan provisions shall expressly identify and quantify the emissions, if any, of any such pollutant or pollutants which will be allowed, in accordance with section 7503(a)(1)(B) of this title, from the construction and operation of major new or modified stationary sources in each such area. The plan shall demonstrate to the satisfaction of the Administrator that the emissions quantified for this purpose will be consistent with the achievement of reasonable further progress and will not interfere with attainment of the applicable national ambient air quality standard by the applicable attainment date."],[0,"(5) Permits for new and modified major stationary sources"],[1,"Such plan provisions shall require permits for the construction and operation of new or modified major stationary sources anywhere in the nonattainment area, in accordance with section 7503 of this title."],[0,"(6) Other measures"],[1,"Such plan provisions shall include enforceable emission limitations, and such other control measures, means or techniques (including economic incentives such as fees, marketable permits, and auctions of emission rights), as well as schedules and timetables for compliance, as may be necessary or appropriate to provide for attainment of such standard in such area by the applicable attainment date specified in this part."],[0,"(7) Compliance with section 7410(a)(2)"],[1,"Such plan provisions shall also meet the applicable provisions of section 7410(a)(2) of this title."],[0,"(8) Equivalent techniques"],[1,"Upon application by any State, the Administrator may allow the use of equivalent modeling, emission inventory, and planning procedures, unless the Administrator determines that the proposed techniques are, in the aggregate, less effective than the methods specified by the Administrator."],[0,"(9) Contingency measures"],[1,"Such plan shall provide for the implementation of specific measures to be undertaken if the area fails to make reasonable further progress, or to attain the national primary ambient air quality standard by the attainment date applicable under this part. Such measures shall be included in the plan revision as contingency measures to take effect in any such case without further action by the State or the Administrator."],[0,"(d) Plan revisions required in response to finding of plan inadequacy"],[0,"Any plan revision for a nonattainment area which is required to be submitted in response to a finding by the Administrator pursuant to section 7410(k)(5) of this title (relating to calls for plan revisions) must correct the plan deficiency (or deficiencies) specified by the Administrator and meet all other applicable plan requirements of section 7410 of this title and this part. The Administrator may reasonably adjust the dates otherwise applicable under such requirements to such revision (except for attainment dates that have not yet elapsed), to the extent necessary to achieve a consistent application of such requirements. In order to facilitate submittal by the States of adequate and approvable plans consistent with the applicable requirements of this chapter, the Administrator shall, as appropriate and from time to time, issue written guidelines, interpretations, and information to the States which shall be available to the public, taking into consideration any such guidelines, interpretations, or information provided before November 15, 1990."],[0,"(e) Future modification of standard"],[0,"If the Administrator relaxes a national primary ambient air quality standard after November 15, 1990, the Administrator shall, within 12 months after the relaxation, promulgate requirements applicable to all areas which have not attained that standard as of the date of such relaxation. Such requirements shall provide for controls which are not less stringent than the controls applicable to areas designated nonattainment before such relaxation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7502?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§7502. Nonattainment plan provisions in general","tname":"The Public Health and Welfare","by":{"0":"","1":""}},{"t":"usc","label":"42 U.S.C. § 1857c","url":"https://www.law.cornell.edu/uscode/text/42/1857c","by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 1857c-7","url":"https://www.law.cornell.edu/uscode/text/42/1857c-7","subs":["(a)(3)"],"by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 1857c-10","url":"https://www.law.cornell.edu/uscode/text/42/1857c-10","by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 7413","url":"https://www.law.cornell.edu/uscode/text/42/7413","by":{"0":""}},{"t":"case","label":"Train v. NRDC","cite":"421 U.S. 60","y":1975,"id":"1974/73-1742","sc":1,"op":4,"sum":"The EPA's construction of the Act permitting treatment of individual variances from state requirements as \"revisions,\" under § 110 (a) (3), of state implementation plans if they will not interfere with timely attainment and subsequent maintenance of national air quality standards, rather than as \"postponements\" under § 110 (f), was sufficiently reasonable to preclude the Court of Appeals from substituting its …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. NRDC","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"op":1,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Morton v. Ruiz","cite":"145 U.S. 199","y":1974,"id":"1973/72-1052","sc":1,"op":2,"sum":"Respondent Ruiz and his wife, Papago Indians, left their reservation in Arizona in 1940 to live in an Indian community a few miles away and Ruiz found employment at a nearby mine.. During a prolonged strike, Ruiz applied for but was denied general assistance benefits under the Snyder Act by the Bureau of Indian Affairs (BIA) because of a provision in the BIA Manual limiting eligibility to Indians living \"on …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"INS v. Wang","cite":"450 U.S. 139","y":1981,"id":"1980/80-485","sc":1,"op":1,"sum":"The Board did not exceed its authority and the Court of Appeals erred in ordering that the case be reopened. Respondents' allegations of hardship were in the main conclusory and unsupported by affidavit, as required by the applicable regulations. Moreover, the Court of Appeals improvidently encroached on the authority which the Act confers on the Attorney General and his delegates to define \"extreme hardship\" in the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Investment Company Institute v. Camp","cite":"401 U.S. 617","y":1971,"id":"1970/61","sc":1,"op":2,"sum":"Petitioners in No. 61, an association of open-end investment companies and several individual such companies, attack (1) portions of the Comptroller of the Currency's Regulation 9, purporting to authorize banks to operate collective investment funds, as violative of the Glass-Steagall Banking Act of 1933 and (2) the Comptroller's approval given First National City Bank to operate a collective investment fund. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Beal v. Doe","cite":"432 U.S. 438","y":1977,"id":"1976/75-554","sc":1,"sum":"The Court held that states could exclude nontherapeutic abortions from coverage under their Medicaid programs. Justice Powell argued that in its provisions, Title XIX of the Social Security Act made no specific reference to abortion nor did it require states to fund every medical procedure which could possibly fall under its umbrella.","sumSrc":"Oyez","by":{"1":""}},{"t":"case","label":"Union Electric Co. v. EPA","cite":"427 U.S. 246","y":1976,"id":"1975/74-1542","sc":1,"op":1,"sum":"Section 110 (a) (1) of the Clean Air Act, as added by the 1970 Amendments to the Act, requires that each State formulate, subject to approval by the Administrator of the Environmental Protection Agency (EPA), an implementation plan providing for attainment of national ambient air quality standards, both primary standards (those necessary to protect the public health) and secondary standards (those necessary to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Hancock v. Train","cite":"426 U.S. 167","y":1976,"id":"1975/74-220","sc":1,"sum":"Although § 118 of the Clean Air Act obligates federal installations discharging air pollutants to join with nonfederal facilities in complying with state \"requirements respecting control and abatement of air pollution,\" obtaining a permit from a State with a federally approved implementation plan is not among such requirements. There cannot be found in § 118, either on its face or in relation to the Act as a whole, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Sierra Club v. Costle","cite":"657 F.2d 298","y":1981,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/657/298/","by":{"1":""}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":""}},{"t":"usc","label":"42 U.S.C. § 1857","url":"https://www.law.cornell.edu/uscode/text/42/1857","subs":["(a)(3)"],"by":{"1":""}},{"t":"usc","label":"42 U.S.C. § 1857c-2","url":"https://www.law.cornell.edu/uscode/text/42/1857c-2","subs":["(a)"],"by":{"1":""}},{"t":"usc","label":"42 U.S.C. § 1857c-4","url":"https://www.law.cornell.edu/uscode/text/42/1857c-4","by":{"1":""}},{"t":"usc","label":"42 U.S.C. § 7503","url":"https://www.law.cornell.edu/uscode/text/42/7503","stext":{"head":"§7503. Permit requirements","paras":[[0,"(a) In general"],[0,"The permit program required by section 7502(b)(6) 1 of this title shall provide that permits to construct and operate may be issued if—"],[1,"(1) in accordance with regulations issued by the Administrator for the determination of baseline emissions in a manner consistent with the assumptions underlying the applicable implementation plan approved under section 7410 of this title and this part, the permitting agency determines that—"],[2,"(A) by the time the source is to commence operation, sufficient offsetting emissions reductions have been obtained, such that total allowable emissions from existing sources in the region, from new or modified sources which are not major emitting facilities, and from the proposed source will be sufficiently less than total emissions from existing sources (as determined in accordance with the regulations under this paragraph) prior to the application for such permit to construct or modify so as to represent (when considered together with the plan provisions required under section 7502 of this title) reasonable further progress (as defined in section 7501 of this title); or"],[2,"(B) in the case of a new or modified major stationary source which is located in a zone (within the nonattainment area) identified by the Administrator, in consultation with the Secretary of Housing and Urban Development, as a zone to which economic development should be targeted, that emissions of such pollutant resulting from the proposed new or modified major stationary source will not cause or contribute to emissions levels which exceed the allowance permitted for such pollutant for such area from new or modified major stationary sources under section 7502(c) of this title;"],[1,"(2) the proposed source is required to comply with the lowest achievable emission rate;"],[1,"(3) the owner or operator of the proposed new or modified source has demonstrated that all major stationary sources owned or operated by such person (or by any entity controlling, controlled by, or under common control with such person) in such State are subject to emission limitations and are in compliance, or on a schedule for compliance, with all applicable emission limitations and standards under this chapter; and 2"],[1,"(4) the Administrator has not determined that the applicable implementation plan is not being adequately implemented for the nonattainment area in which the proposed source is to be constructed or modified in accordance with the requirements of this part; and"],[1,"(5) an analysis of alternative sites, sizes, production processes, and environmental control techniques for such proposed source demonstrates that benefits of the proposed source significantly outweigh the environmental and social costs imposed as a result of its location, construction, or modification."],[0,"Any emission reductions required as a precondition of the issuance of a permit under paragraph (1) shall be federally enforceable before such permit may be issued."],[0,"(b) Prohibition on use of old growth allowances"],[0,"Any growth allowance included in an applicable implementation plan to meet the requirements of section 7502(b)(5) of this title (as in effect immediately before November 15, 1990) shall not be valid for use in any area that received or receives a notice under section 7410(a)(2)(H)(ii) of this title (as in effect immediately before November 15, 1990) or under section 7410(k)(1) of this title that its applicable implementation plan containing such allowance is substantially inadequate."],[0,"(c) Offsets"],[0,"(1) The owner or operator of a new or modified major stationary source may comply with any offset requirement in effect under this part for increased emissions of any air pollutant only by obtaining emission reductions of such air pollutant from the same source or other sources in the same nonattainment area, except that the State may allow the owner or operator of a source to obtain such emission reductions in another nonattainment area if (A) the other area has an equal or higher nonattainment classification than the area in which the source is located and (B) emissions from such other area contribute to a violation of the national ambient air quality standard in the nonattainment area in which the source is located. Such emission reductions shall be, by the time a new or modified source commences operation, in effect and enforceable and shall assure that the total tonnage of increased emissions of the air pollutant from the new or modified source shall be offset by an equal or greater reduction, as applicable, in the actual emissions of such air pollutant from the same or other sources in the area."],[0,"(2) Emission reductions otherwise required by this chapter shall not be creditable as emissions reductions for purposes of any such offset requirement. Incidental emission reductions which are not otherwise required by this chapter shall be creditable as emission reductions for such purposes if such emission reductions meet the requirements of paragraph (1)."],[0,"(d) Control technology information"],[0,"The State shall provide that control technology information from permits issued under this section will be promptly submitted to the Administrator for purposes of making such information available through the RACT/BACT/LAER clearinghouse to other States and to the general public."],[0,"(e) Rocket engines or motors"],[0,"The permitting authority of a State shall allow a source to offset by alternative or innovative means emission increases from rocket engine and motor firing, and cleaning related to such firing, at an existing or modified major source that tests rocket engines or motors under the following conditions:"],[1,"(1) Any modification proposed is solely for the purpose of expanding the testing of rocket engines or motors at an existing source that is permitted to test such engines on November 15, 1990."],[1,"(2) The source demonstrates to the satisfaction of the permitting authority of the State that it has used all reasonable means to obtain and utilize offsets, as determined on an annual basis, for the emissions increases beyond allowable levels, that all available offsets are being used, and that sufficient offsets are not available to the source."],[1,"(3) The source has obtained a written finding from the Department of Defense, Department of Transportation, National Aeronautics and Space Administration or other appropriate Federal agency, that the testing of rocket motors or engines at the facility is required for a program essential to the national security."],[1,"(4) The source will comply with an alternative measure, imposed by the permitting authority, designed to offset any emission increases beyond permitted levels not directly offset by the source. In lieu of imposing any alternative offset measures, the permitting authority may impose an emissions fee to be paid to such authority of a State which shall be an amount no greater than 1.5 times the average cost of stationary source control measures adopted in that area during the previous 3 years. The permitting authority shall utilize the fees in a manner that maximizes the emissions reductions in that area."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7503?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7503. Permit requirements","tname":"The Public Health and Welfare","by":{"1":""}},{"t":"usc","label":"42 U.S.C. § 7601","url":"https://www.law.cornell.edu/uscode/text/42/7601","subs":["(a)(1)"],"by":{"1":""}},{"t":"usc","label":"42 U.S.C. § 7411","url":"https://www.law.cornell.edu/uscode/text/42/7411","subs":["(a)(3)"],"by":{"1":""}},{"t":"usc","label":"42 U.S.C. § 7501","url":"https://www.law.cornell.edu/uscode/text/42/7501","subs":["(4)"],"stext":{"head":"§7501. Definitions","paras":[[0,"For the purpose of this part—"],[1,"(1) Reasonable further progress.—The term \"reasonable further progress\" means such annual incremental reductions in emissions of the relevant air pollutant as are required by this part or may reasonably be required by the Administrator for the purpose of ensuring attainment of the applicable national ambient air quality standard by the applicable date."],[1,"(2) Nonattainment area.—The term \"nonattainment area\" means, for any air pollutant, an area which is designated \"nonattainment\" with respect to that pollutant within the meaning of section 7407(d) of this title."],[1,"(3) The term \"lowest achievable emission rate\" means for any source, that rate of emissions which reflects—"],[2,"(A) the most stringent emission limitation which is contained in the implementation plan of any State for such class or category of source, unless the owner or operator of the proposed source demonstrates that such limitations are not achievable, or"],[2,"(B) the most stringent emission limitation which is achieved in practice by such class or category of source, whichever is more stringent."],[1,"In no event shall the application of this term permit a proposed new or modified source to emit any pollutant in excess of the amount allowable under applicable new source standards of performance."],[1,"(4) The terms \"modifications\" and \"modified\" mean the same as the term \"modification\" as used in section 7411(a)(4) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7501?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7501. Definitions","tname":"The Public Health and Welfare","by":{"1":""}},{"t":"usc","label":"42 U.S.C. § 7470","url":"https://www.law.cornell.edu/uscode/text/42/7470","by":{"1":""}},{"t":"usc","label":"42 U.S.C. § 7475","url":"https://www.law.cornell.edu/uscode/text/42/7475","subs":["(a)"],"by":{"1":""}},{"t":"usc","label":"42 U.S.C. § 7607","url":"https://www.law.cornell.edu/uscode/text/42/7607","subs":["(b)(1)"],"stext":{"head":"§7607. Administrative proceedings and judicial review","paras":[[0,"(a) Administrative subpenas; confidentiality; witnesses"],[0,"In connection with any determination under section 7410(f) of this title, or for purposes of obtaining information under section 7521(b)(4) 1 or 7545(c)(3) of this title, any investigation, monitoring, reporting requirement, entry, compliance inspection, or administrative enforcement proceeding under the 2 chapter (including but not limited to section 7413, section 7414, section 7420, section 7429, section 7477, section 7524, section 7525, section 7542, section 7603, or section 7606 of this title),,3 the Administrator may issue subpenas for the attendance and testimony of witnesses and the production of relevant papers, books, and documents, and he may administer oaths. Except for emission data, upon a showing satisfactory to the Administrator by such owner or operator that such papers, books, documents, or information or particular part thereof, if made public, would divulge trade secrets or secret processes of such owner or operator, the Administrator shall consider such record, report, or information or particular portion thereof confidential in accordance with the purposes of section 1905 of title 18, except that such paper, book, document, or information may be disclosed to other officers, employees, or authorized representatives of the United States concerned with carrying out this chapter, to persons carrying out the National Academy of Sciences' study and investigation provided for in section 7521(c) of this title, or when relevant in any proceeding under this chapter. Witnesses summoned shall be paid the same fees and mileage that are paid witnesses in the courts of the United States. In case of contumacy or refusal to obey a subpena served upon any person under this subparagraph,4 the district court of the United States for any district in which such person is found or resides or transacts business, upon application by the United States and after notice to such person, shall have jurisdiction to issue an order requiring such person to appear and give testimony before the Administrator to appear and produce papers, books, and documents before the Administrator, or both, and any failure to obey such order of the court may be punished by such court as a contempt thereof."],[0,"(b) Judicial review"],[0,"(1) A petition for review of action of the Administrator in promulgating any national primary or secondary ambient air quality standard, any emission standard or requirement under section 7412 of this title, any standard of performance or requirement under section 7411 of this title,,3 any standard under section 7521 of this title (other than a standard required to be prescribed under section 7521(b)(1) of this title), any determination under section 7521(b)(5) 1 of this title, any control or prohibition under section 7545 of this title, any standard under section 7571 of this title, any rule issued under section 7413, 7419, or under section 7420 of this title, or any other nationally applicable regulations promulgated, or final action taken, by the Administrator under this chapter may be filed only in the United States Court of Appeals for the District of Columbia. A petition for review of the Administrator's action in approving or promulgating any implementation plan under section 7410 of this title or section 7411(d) of this title, any order under section 7411(j) of this title, under section 7412 of this title, under section 7419 of this title, or under section 7420 of this title, or his action under section 1857c–10(c)(2)(A), (B), or (C) of this title (as in effect before August 7, 1977) or under regulations thereunder, or revising regulations for enhanced monitoring and compliance certification programs under section 7414(a)(3) of this title, or any other final action of the Administrator under this chapter (including any denial or disapproval by the Administrator under subchapter I) which is locally or regionally applicable may be filed only in the United States Court of Appeals for the appropriate circuit. Notwithstanding the preceding sentence a petition for review of any action referred to in such sentence may be filed only in the United States Court of Appeals for the District of Columbia if such action is based on a determination of nationwide scope or effect and if in taking such action the Administrator finds and publishes that such action is based on such a determination. Any petition for review under this subsection shall be filed within sixty days from the date notice of such promulgation, approval, or action appears in the Federal Register, except that if such petition is based solely on grounds arising after such sixtieth day, then any petition for review under this subsection shall be filed within sixty days after such grounds arise. The filing of a petition for reconsideration by the Administrator of any otherwise final rule or action shall not affect the finality of such rule or action for purposes of judicial review nor extend the time within which a petition for judicial review of such rule or action under this section may be filed, and shall not postpone the effectiveness of such rule or action."],[0,"(2) Action of the Administrator with respect to which review could have been obtained under paragraph (1) shall not be subject to judicial review in civil or criminal proceedings for enforcement. Where a final decision by the Administrator defers performance of any nondiscretionary statutory action to a later time, any person may challenge the deferral pursuant to paragraph (1)."],[0,"(c) Additional evidence"],[0,"In any judicial proceeding in which review is sought of a determination under this chapter required to be made on the record after notice and opportunity for hearing, if any party applies to the court for leave to adduce additional evidence, and shows to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the proceeding before the Administrator, the court may order such additional evidence (and evidence in rebuttal thereof) to be taken before the Administrator, in such manner and upon such terms and conditions as to 5 the court may deem proper. The Administrator may modify his findings as to the facts, or make new findings, by reason of the additional evidence so taken and he shall file such modified or new findings, and his recommendation, if any, for the modification or setting aside of his original determination, with the return of such additional evidence."],[0,"(d) Rulemaking"],[0,"(1) This subsection applies to—"],[1,"(A) the promulgation or revision of any national ambient air quality standard under section 7409 of this title,"],[1,"(B) the promulgation or revision of an implementation plan by the Administrator under section 7410(c) of this title,"],[1,"(C) the promulgation or revision of any standard of performance under section 7411 of this title, or emission standard or limitation under section 7412(d) of this title, any standard under section 7412(f) of this title, or any regulation under section 7412(g)(1)(D) and (F) 6 of this title, or any regulation under section 7412(m) or (n) of this title,"],[1,"(D) the promulgation of any requirement for solid waste combustion under section 7429 of this title,"],[1,"(E) the promulgation or revision of any regulation pertaining to any fuel or fuel additive under section 7545 of this title,"],[1,"(F) the promulgation or revision of any aircraft emission standard under section 7571 of this title,"],[1,"(G) the promulgation or revision of any regulation under subchapter IV–A (relating to control of acid deposition),"],[1,"(H) promulgation or revision of regulations pertaining to primary nonferrous smelter orders under section 7419 of this title (but not including the granting or denying of any such order),"],[1,"(I) promulgation or revision of regulations under subchapter VI (relating to stratosphere and ozone protection),"],[1,"(J) promulgation or revision of regulations under part C of subchapter I (relating to prevention of significant deterioration of air quality and protection of visibility),"],[1,"(K) promulgation or revision of regulations under section 7521 of this title and test procedures for new motor vehicles or engines under section 7525 of this title, and the revision of a standard under section 7521(a)(3) of this title,"],[1,"(L) promulgation or revision of regulations for noncompliance penalties under section 7420 of this title,"],[1,"(M) promulgation or revision of any regulations promulgated under section 7541 of this title (relating to warranties and compliance by vehicles in actual use),"],[1,"(N) action of the Administrator under section 7426 of this title (relating to interstate pollution abatement),"],[1,"(O) the promulgation or revision of any regulation pertaining to consumer and commercial products under section 7511b(e) of this title,"],[1,"(P) the promulgation or revision of any regulation pertaining to field citations under section 7413(d)(3) of this title,"],[1,"(Q) the promulgation or revision of any regulation pertaining to urban buses or the clean-fuel vehicle, clean-fuel fleet, and clean fuel programs under part C of subchapter II,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7607?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7607. Administrative proceedings and judicial review","tname":"The Public Health and Welfare","by":{"1":""}}]};